import * as fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {readCommittedPolicy,readCommittedUrlOriginPolicy,committedUrlPoliciesCurrent,committedUrlPoliciesCurrentAsync} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/policy-snapshot.ts';
import {readUrlParentAdoption} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/url-parent-adoption.ts';
import {buildDossierScreen} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/screen.ts';
import {createSessionProfile,createOrderedDesignSessionProfile} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/session-profile.ts';
import {createUrlSessionAudit} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/url-session-audit.ts';
import {bindCurrentEffectiveUrlRun} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/effective-run-record.ts';
import {urlRunModeAuthority} from '/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/polaris-dossier/src/url-mode-registry.ts';
const cut=JSON.parse(await fs.readFile('/home/orca/.tmp/f3-stop-resume-fifth-cut.json','utf8'));
const root=path.dirname(cut.governanceRoot),host=path.dirname(path.dirname(cut.hidden));
const base=readCommittedPolicy(root),origin=readCommittedUrlOriginPolicy(root);
if(!base.ok||!origin.ok)throw Error('snapshot'); const parent=readUrlParentAdoption(root,origin.binding.sha256);if(!parent)throw Error('parent');
const screen=buildDossierScreen(base.bytes,true,null,'private');if(!screen.ok)throw Error('screen');
const mode=urlRunModeAuthority(host,text=>screen.screen.screenSecrets(text)===undefined);
const declaration=JSON.parse(await fs.readFile(path.join(cut.run,'url-declaration.json'),'utf8'));
const authority=bindCurrentEffectiveUrlRun(cut.run,mode,{baseSha256:declaration.baseRunSha256,sidecarSha256:(await import('/home/orca/.tmp/syzygy-beads-looper-20261114-54ebc9f1/d10-f3-stop-cut-regression/packages/support/src/sha256.ts')).sha256(await fs.readFile(path.join(cut.run,'url-declaration.json')))});if(!authority)throw Error('authority');
const stoppedName=(await fs.readdir(host)).find(name=>name.endsWith('.stopped.json'))!;
const sealed=JSON.parse(await fs.readFile(path.join(host,stoppedName),'utf8'));
console.log('seal keys',Object.keys(sealed));
const roles=(sealed.record??sealed).roles;
if(!Array.isArray(roles))throw Error('roles');
const profiles=roles.map(saved=>{const issued=(saved.role==='design'?createOrderedDesignSessionProfile:createSessionProfile)(saved.input);if(!issued.ok)throw Error('profile');return issued.value.profile});
for(const variant of ['repeated','single'] as const){
 const dir=await fs.mkdtemp(path.join(os.homedir(),'.tmp/f3-audit-guard-cost-'));await fs.chmod(dir,0o700);
 const stats={variant,currentCalls:0,syncCalls:0,asyncCalls:0,authorityCalls:0,syncMs:0,asyncMs:0,authorityMs:0,currentMs:0,falseResults:0};
 const sync=()=>{stats.syncCalls++;const at=performance.now();const ok=committedUrlPoliciesCurrent(root,base.binding,origin.binding,parent);stats.syncMs+=performance.now()-at;return ok};
 const current=()=>{if(!sync())return false;stats.authorityCalls++;const at=performance.now();const ok=authority();stats.authorityMs+=performance.now()-at;return ok};
 const guard=async()=>{stats.currentCalls++;const at=performance.now();let ok=current();if(ok&&variant==='repeated'){stats.asyncCalls++;const began=performance.now();ok=await committedUrlPoliciesCurrentAsync(root,base.binding,origin.binding,parent);stats.asyncMs+=performance.now()-began;ok=ok&&current();}stats.currentMs+=performance.now()-at;if(!ok)stats.falseResults++;return ok};
 const ref=cut.expected.declarations.author,at=performance.now(); const {role:_role,...binding}=ref.scope.binding;
 const audit=await createUrlSessionAudit({parent:dir,name:'cost',binding,originPolicySha256:origin.binding.sha256,project:ref.payload.project,pin:ref.payload.pin,principal:ref.payload.principal,profiles,declaredClasses:ref.payload.declaredClasses,screen:screen.screen,deadline:cut.deadline,current:guard});
 console.log(JSON.stringify({...stats,elapsedMs:performance.now()-at,ok:audit.ok}));
 if(audit.ok)await audit.close();await fs.rm(dir,{recursive:true,force:true});
}
